    // ─────────── فصل ۱: رئیس برومدن ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "Chief Bromden", titlePersian = "رئیس برومدن",
        paragraphs = listOf(
            StoryParagraph("My name is Chief Bromden, and I am a patient in a mental hospital in Oregon, and I have been here longer than anyone can remember.", "نام من رئیس برومدن است و من بیماری در بیمارستان روانی در اورگان هستم و بیشتر از آنچه هر کسی به یاد بیاورد اینجا بوده‌ام."),
            StoryParagraph("I am half Native American — half white, my father was a chief of the Columbia Gorge tribe, my mother was a white woman who did not want me to be an Indian.", "من نیمه سرخ‌پوست هستم — نیمه سفید، پدرم رئیس قبیله دره کلمبیا بود، مادرم زنی سفیدپوست بود که نمی‌خواست من سرخ‌پوست باشم."),
            StoryParagraph("I am very tall — six feet seven inches — and very strong; I could lift a piano with one hand if I wanted to, but I have not wanted to for years.", "من خیلی بلندقد هستم — شش فوت و هفت اینچ — و خیلی قوی؛ می‌توانستم با یک دست پیانو را بلند کنم اگر می‌خواستم، اما سال‌هاست نخواسته‌ام."),
            StoryParagraph("I pretend to be deaf and mute; I have pretended for so long that most people have forgotten I was ever otherwise.", "تظاهر می‌کنم کر و لالم؛ اینقدر طولانی تظاهر کرده‌ام که بیشتر مردم فراموش کرده‌اند زمانی غیر از این بودم."),
            StoryParagraph("Nobody knows that I can hear everything, that I can understand everything, that I remember everything.", "هیچ‌کس نمی‌داند که می‌توانم همه چیز را بشنوم، همه چیز را بفهمم، همه چیز را به یاد بیاورم."),
            StoryParagraph("I sit in the corner of the day room, and I watch, and I wait, and I see everything that happens in this ward.", "در گوشه اتاق روز می‌نشستم و تماشا می‌کنم و منتظر می‌مانم و هر چیزی که در این بخش اتفاق می‌افتد را می‌بینم."),
            StoryParagraph("The ward is run by a woman we call the Big Nurse — her real name is Nurse Ratched, and she is the most terrifying person I have ever known.", "بخش توسط زنی که پرستار بزرگ صدایش می‌زنیم اداره می‌شود — نام واقعی‌اش پرستار رچد است و هراسناک‌ترین شخصی است که هرگز شناخته‌ام."),
            StoryParagraph("She is not terrifying because she shouts, or because she is violent; she is terrifying because she is calm, and patient, and utterly in control.", "او هراسناک نیست چون فریاد می‌زند، یا چون خشن است؛ هراسناک است چون آرام است، صبور و کاملاً در کنترل."),
            StoryParagraph("She has a face like a doll — smooth, painted, expressionless; her smile never reaches her eyes; her voice is always soft and reasonable.", "صورتی مثل عروسک دارد — صاف، رنگ‌آمیزی‌شده، بی‌بیان؛ لبخندش هرگز به چشمانش نمی‌رسد؛ صدایش همیشه نرم و معقول است."),
            StoryParagraph("She controls the ward through a thousand small mechanisms: the schedule, the pills, the meetings, the rules, the silences.", "او بخش را از طریق هزار مکانیزم کوچک کنترل می‌کند: برنامه، قرص‌ها، جلسات، قوانین، سکوت‌ها."),
            StoryParagraph("The patients here are divided into two groups: the Acutes and the Chronics.", "بیماران اینجا به دو گروه تقسیم می‌شوند: حادها و مزمن‌ها."),
            StoryParagraph("The Acutes are the ones who might get better; they might leave someday; they might have a life outside these walls.", "حادها کسانی هستند که ممکن است بهتر شوند؛ ممکن است روزی بروند؛ ممکن است زندگی‌ای بیرون از این دیوارها داشته باشند."),
            StoryParagraph("The Chronics are the ones who will never get better; they will stay here until they die; they are the walking dead, the living machines.", "مزمن‌ها کسانی هستند که هرگز بهتر نمی‌شوند؛ تا مرگ اینجا می‌مانند؛ مردگان متحرکند، ماشین‌های زنده."),
            StoryParagraph("I am a Chronic; I have been a Chronic for so long that I have forgotten what it was like to be anything else.", "من مزمن هستم؛ اینقدر طولانی مزمن بوده‌ام که فراموش کرده‌ام غیر از این بودن چه حسی داشت."),
            StoryParagraph("The Chronics come in three kinds: the Walkers, who can still move around; the Wheelers, who are in wheelchairs; and the Vegetables, who cannot move at all.", "مزمن‌ها سه نوع هستند: راه‌رونده‌ها که هنوز می‌توانند حرکت کنند؛ چرخ‌دارها که در ویلچرند؛ و سبزیجات که اصلاً نمی‌توانند حرکت کنند."),
            StoryParagraph("I am a Walker; I walk around the ward, and I sweep the floors, and I do not speak, and nobody notices me.", "من راه‌رونده‌ام؛ در بخش راه می‌روم و کف‌ها را جارو می‌کنم و صحبت نمی‌کنم و هیچ‌کس متوجهم نمی‌شود."),
            StoryParagraph("There is a fog that comes into the ward sometimes — or at least, I think there is a fog; it may be real, or it may be in my mind.", "گاهی مهی به بخش می‌آید — یا حداقل، فکر می‌کنم مهی هست؛ ممکن است واقعی باشد یا در ذهنم."),
            StoryParagraph("The fog comes when things are bad; it comes when I am afraid; it comes when the Big Nurse is winning.", "مه وقتی چیزها بد است می‌آید؛ وقتی می‌ترسم؛ وقتی پرستار بزرگ در حال بردن است."),
            StoryParagraph("The fog is thick and grey and suffocating; it hides everything; it makes everything the same; it makes it impossible to think, or to feel, or to move.", "مه غلیظ و خاکستری و خفه‌کننده است؛ همه چیز را پنهان می‌کند؛ همه چیز را یکسان می‌کند؛ فکر کردن یا احساس کردن یا حرکت کردن را ناممکن می‌کند."),
            StoryParagraph("The Big Nurse controls the fog; she has a machine somewhere, a machine with levers and buttons, and she uses it to keep us calm.", "پرستار بزرگ مه را کنترل می‌کند؛ جایی ماشینی دارد، ماشینی با اهرم‌ها و دکمه‌ها و از آن استفاده می‌کند تا ما را آرام نگه دارد."),
            StoryParagraph("The machine makes a humming sound; I can hear it sometimes, late at night, when everything else is quiet.", "ماشین صدای همهمه‌ای ایجاد می‌کند؛ گاهی می‌توانم بشنومش، دیروقت شب، وقتی همه چیز ساکت است."),
            StoryParagraph("I have been in this ward for ten years, or maybe fifteen, or maybe twenty; I have lost count; time does not pass here the way it passes outside.", "ده سال، یا شاید پانزده، یا شاید بیست سال است که در این بخشم؛ شمارش را از دست داده‌ام؛ زمان اینجا مثل بیرون نمی‌گذرد."),
            StoryParagraph("Every day is the same: we wake up, we take our pills, we eat breakfast, we go to the day room, we attend meetings, we eat lunch, we rest, we attend more meetings, we eat dinner, we take more pills, we go to bed.", "هر روز یکسان است: بیدار می‌شویم، قرص‌هایمان را می‌خوریم، صبحانه می‌خوریم، به اتاق روز می‌رویم، در جلسات شرکت می‌کنیم، ناهار می‌خوریم، استراحت می‌کنیم، در جلسات بیشتری شرکت می‌کنیم، شام می‌خوریم، قرص‌های بیشتری می‌خوریم، به تخت می‌رویم."),
            StoryParagraph("The pills make us calm; they make us forget; they make us not care about anything; they make us good patients.", "قرص‌ها ما را آرام می‌کنند؛ به فراموشی می‌کشانند؛ وادارمان می‌کنند به هیچ چیز اهمیت ندهیم؛ بیماران خوبی می‌سازند از ما."),
            StoryParagraph("The meetings are called Therapeutic Community Meetings; in these meetings, we are supposed to talk about our feelings, to share our problems, to help each other heal.", "جلسات را جلسات جامعه درمانی می‌نامند؛ در این جلسات، قرار است درباره احساساتمان صحبت کنیم، مشکلاتمان را قسمت کنیم، به هم کمک کنیم بهبود یابیم."),
            StoryParagraph("But the meetings are not really therapy; the meetings are a weapon; the Big Nurse uses them to humiliate us, to break us, to keep us weak.", "اما جلسات واقعاً درمان نیستند؛ جلسات سلاحی هستند؛ پرستار بزرگ از آنها برای تحقیرمان استفاده می‌کند، برای شکستنمان، برای ضعیف نگه داشتنمان."),
            StoryParagraph("In the meetings, she asks questions that have no right answers; she makes us attack each other; she makes us betray each other's secrets.", "در جلسات، پرسش‌هایی می‌پرسد که پاسخ درست ندارند؛ وادارمان می‌کند به هم حمله کنیم؛ وادارمان می‌کند رازهای هم را لو بدهیم."),
            StoryParagraph("The patients who resist her are punished; the patients who obey her are rewarded; and slowly, we learn to do exactly what she wants.", "بیمارانی که مقاومتش می‌کنند مجازات می‌شوند؛ بیمارانی که اطاعتش می‌کنند پاداش می‌گیرند؛ و به‌آرامی، یاد می‌گیریم دقیقاً همان کاری را بکنیم که او می‌خواهد."),
            StoryParagraph("But there is one patient who did not learn; there is one patient who cannot be broken; and that patient is about to arrive.", "اما بیماری هست که یاد نگرفت؛ بیماری هست که نمی‌شود شکست؛ و آن بیمار در شرف ورود است."),
            StoryParagraph("His name is McMurphy, and he is coming to change everything.", "نامش مک‌مرفی است و می‌آید تا همه چیز را تغییر دهد."),
            StoryParagraph("I do not know it yet, but my life is about to change; the fog is about to lift; the machine is about to break.", "هنوز نمی‌دانم، اما زندگی‌ام در شرف تغییر است؛ مه در شرف بلند شدن؛ ماشین در شرف شکستن."),
            StoryParagraph("And when it breaks, I will be free — or I will be destroyed; but either way, I will no longer be a machine.", "و چون بشکند، آزاد خواهم شد — یا نابود خواهم شد؛ اما در هر حال، دیگر ماشین نخواهم بود."),
            StoryParagraph("This is the story of how I became a man again; this is the story of how McMurphy saved me.", "این داستان این است که چگونه دوباره انسان شدم؛ این داستان این است که چگونه مک‌مرفی نجاتم داد."),
            StoryParagraph("I have been silent for years; now I will speak.", "سال‌ها ساکت بوده‌ام؛ حالا صحبت خواهم کرد."),
            StoryParagraph("I have been invisible for years; now I will be seen.", "سال‌ها نامرئی بوده‌ام؛ حالا دیده خواهم شد."),
            StoryParagraph("I have been dead for years; now I will live.", "سال‌ها مرده بوده‌ام؛ حالا زندگی خواهم کرد."),
            StoryParagraph("And so my story begins, in the fog, in the ward, in the shadow of the Big Nurse.", "و اینگونه داستانم آغاز می‌شود، در مه، در بخش، در سایه پرستار بزرگ."),
            StoryParagraph("And it begins with the arrival of a man who laughed.", "و با ورود مردی آغاز می‌شود که خندید.")
        )
    )

    // ─────────── فصل ۲: مک‌مرفی ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "McMurphy", titlePersian = "مک‌مرفی",
        paragraphs = listOf(
            StoryParagraph("McMurphy arrived on a Thursday morning, in the middle of the therapeutic community meeting, and he arrived like a storm.", "مک‌مرفی صبح پنجشنبه‌ای آمد، در میانه جلسه جامعه درمانی و مثل طوفانی آمد."),
            StoryParagraph("He was a big man, tall and broad, with a red face and bright blue eyes and a grin that seemed to have no off-switch.", "مردی بزرگ بود، بلند و پهن، با صورتی سرخ و چشمانی آبی روشن و لبخندی که به نظر می‌رسید خاموشی ندارد."),
            StoryParagraph("He wore a heavy leather jacket and a cap, and he walked into the ward like he owned it.", "کاپشن چرمی سنگینی پوشیده بود و کلاهی و مثل صاحب ملک به بخش وارد شد."),
            StoryParagraph("The Big Nurse looked up from her desk, and for a moment — just a moment — her smooth face flickered with something that might have been surprise.", "پرستار بزرگ از میزش سر بلند کرد و لحظه‌ای — فقط لحظه‌ای — صورت صافش با چیزی که می‌توانست تعجب باشد لرزید."),
            StoryParagraph("'Good morning,' McMurphy said, loudly, cheerfully, in a voice that filled the room. 'I hear you got a party going on.'", "مک‌مرفی بلند، شادمانه، با صدایی که اتاق را پر کرد گفت: «صبح بخیر. شنیدم مهمانی دارید.»"),
            StoryParagraph("The patients stared at him; nobody had spoken to the Big Nurse like that, not in years, not in decades.", "بیماران خیره‌اش شدند؛ هیچ‌کس اینطور با پرستار بزرگ صحبت نکرده بود، نه در سال‌ها، نه در دهه‌ها."),
            StoryParagraph("'You are Mr. McMurphy,' the Big Nurse said, and her voice was calm, and her smile was smooth.", "پرستار بزرگ گفت: «شما آقای مک‌مرفی هستید.» و صدایش آرام بود و لبخندش صاف."),
            StoryParagraph("'That's me,' McMurphy said. 'Ace of spades. King of the card game. And you must be Big Nurse Ratched. I've heard a lot about you.'", "مک‌مرفی گفت: «خودمم. آس پیک. پادشاه بازی ورق. و شما باید پرستار بزرگ رچد باشید. خیلی از شما شنیده‌ام.»"),
            StoryParagraph("'I am Miss Ratched,' she said. 'And this is a hospital, not a card game.'", "گفت: «من خانم رچد هستم. و این بیمارستان است، نه بازی ورق.»"),
            StoryParagraph("'Whatever you say, ma'am,' McMurphy said, and he winked at the nearest patient, and the patient looked terrified.", "مک‌مرفی گفت: «هر چه شما بگویید، خانم.» و به نزدیک‌ترین بیمار چشمک زد و بیمار وحشت‌زده به نظر رسید."),
            StoryParagraph("McMurphy had come to the hospital, I learned later, to escape a prison sentence.", "بعداً فهمیدم مک‌مرفی به بیمارستان آمده بود تا از حکم زندان فرار کند."),
            StoryParagraph("He had been arrested for statutory rape — the girl had lied about her age — and he had been sentenced to a work farm.", "او برای تجاوز قانونی دستگیر شده بود — دختر درباره سنش دروغ گفته بود — و به مزرعه کار محکوم شده بود."),
            StoryParagraph("But he had decided that a mental hospital would be easier than a work farm.", "اما تصمیم گرفته بود بیمارستان روانی از مزرعه کار راحت‌تر است."),
            StoryParagraph("He had faked insanity — or so he thought — and he had been sent here for evaluation.", "تظاهر به دیوانگی کرده بود — یا اینطور فکر می‌کرد — و برای ارزیابی به اینجا فرستاده شده بود."),
            StoryParagraph("He thought he could serve his time here, playing cards, flirting with the nurses, then walk out free.", "فکر می‌کرد می‌تواند دورانش را اینجا بگذراند، ورق بازی کند، با پرستارها لاس بزند و بعد آزاد بیرون برود."),
            StoryParagraph("He did not know what he was getting into; he did not know that the Big Nurse did not let anyone walk out free.", "نمی‌دانست به چه چیزی وارد می‌شود؛ نمی‌دانست پرستار بزرگ نمی‌گذارد هیچ‌کس آزاد بیرون برود."),
            StoryParagraph("But he was about to learn; and we — all of us, the patients of the ward — were about to learn too.", "اما در شرف یادگیری بود؛ و ما — همه‌مان، بیماران بخش — در شرف یادگیری بودیم."),
            StoryParagraph("McMurphy introduced himself to everyone in the ward, one by one, shaking hands, asking names, telling jokes.", "مک‌مرفی خودش را به همه در بخش معرفی کرد، یکی‌یکی، دست داد، اسم پرسید، جوک گفت."),
            StoryParagraph("He met Harding, the president of the Patient's Council, an intelligent man with shaking hands and a nervous laugh.", "او هاردینگ را ملاقات کرد، رئیس شورای بیماران، مردی باهوش با دستان لرزان و خنده‌ای عصبی."),
            StoryParagraph("He met Billy Bibbit, a young man with a stutter and a fear of women so profound that he could barely speak to them.", "او بیلی بیبیت را ملاقات کرد، جوانی با لکنت و ترسی از زنان چنان عمیق که به‌سختی می‌توانست با آن‌ها صحبت کند."),
            StoryParagraph("He met Martini, who saw things that were not there; and Scanlon, who liked to blow things up; and Cheswick, who was always arguing about cigarettes.", "مارتینی را ملاقات کرد که چیزهایی که آنجا نبودند می‌دید؛ و اسکانلون که دوست داشت چیزها را منفجر کند؛ و چزویک که همیشه سر سیگار بحث می‌کرد."),
            StoryParagraph("And then he came to me, sitting in the corner, pretending to be deaf, pretending to be mute, pretending to be nothing at all.", "و بعد به سراغ من آمد، نشسته در گوشه، تظاهر به کری، تظاهر به لالی، تظاهر به هیچ بودن."),
            StoryParagraph("He looked at me for a long moment, and I looked at him, and something passed between us.", "مدت طولانی نگاهم کرد و من نگاهش کردم و چیزی میانمان رد شد."),
            StoryParagraph("'How are you, Chief?' he said, and he shook my hand, and his grip was warm and strong.", "گفت: «چطوری رئیس؟» و دستم را فشرد و دستش گرم و قوی بود."),
            StoryParagraph("Nobody had called me Chief in years; nobody had shaken my hand in years; nobody had looked at me like I was a human being in years.", "سال‌ها بود هیچ‌کس رئیس صدایم نکرده بود؛ سال‌ها بود هیچ‌کس دستم را نفشرده بود؛ سال‌ها بود هیچ‌کس مثل یک انسان نگاهم نکرده بود."),
            StoryParagraph("'You're a big son of a bitch,' McMurphy said. 'You could probably lift that goddamn control panel right off its base.'", "مک‌مرفی گفت: «یک حرومزاده بزرگی هستی. احتمالاً می‌توانی آن پنل کنترل لعنتی را از پایه‌اش بلند کنی.»"),
            StoryParagraph("He pointed to the heavy control panel that stood in the center of the ward, the one connected to the Big Nurse's machine.", "به پنل کنترل سنگین که در مرکز بخش ایستاده بود اشاره کرد، همان که به ماشین پرستار بزرگ وصل بود."),
            StoryParagraph("'Nobody can lift that,' I said — but I did not say it, because I had not spoken in years, and I had forgotten how.", "گفتم: «هیچ‌کس نمی‌تواند بلندش کند» — اما نگفتم، چون سال‌ها صحبت نکرده بودم و فراموش کرده بودم چطور."),
            StoryParagraph("But McMurphy heard me anyway; he heard me in my silence; he heard me in my eyes.", "اما مک‌مرفی به هر حال شنیدم؛ در سکوتم شنیدم؛ در چشمانم شنیدم."),
            StoryParagraph("'We'll see about that,' he said, and he smiled, and he walked away, and I knew that something had changed.", "گفت: «خواهیم دید.» و لبخند زد و رفت و من دانستم چیزی تغییر کرده."),
            StoryParagraph("I had not felt hope in so long that I had forgotten what it felt like.", "اینقدر طولانی امید حس نکرده بودم که فراموش کرده بودم چه حسی دارد."),
            StoryParagraph("But there it was — small, weak, almost extinguished — a spark of something.", "اما آنجا بود — کوچک، ضعیف، تقریباً خاموش — جرقه‌ای از چیزی."),
            StoryParagraph("McMurphy had brought it with him; McMurphy had brought the spark; and the spark was about to become a fire.", "مک‌مرفی آن را با خود آورده بود؛ مک‌مرفی جرقه را آورده بود؛ و جرقه در شرف تبدیل به آتش بود."),
            StoryParagraph("That night, in my bed, in the dark, I lay awake and listened to the machine hum.", "آن شب، در تختم، در تاریکی، بیدار دراز کشیدم و به همهمه ماشین گوش دادم."),
            StoryParagraph("And for the first time in years, I thought: maybe I can break it.", "و برای نخستین بار در سال‌ها فکر کردم: شاید بتوانم بشکنمش."),
            StoryParagraph("Maybe I can break it, and maybe I can escape, and maybe I can be free.", "شاید بتوانم بشکنمش، شاید بتوانم فرار کنم، شاید بتوانم آزاد باشم."),
            StoryParagraph("Maybe — just maybe — the Big Nurse is not all-powerful.", "شاید — فقط شاید — پرستار بزرگ قدرتمند مطلق نیست."),
            StoryParagraph("And so McMurphy's story began, and so my story began, and so the story of all the men in that ward began.", "و اینگونه داستان مک‌مرفی آغاز شد و اینگونه داستان من و داستان همه مردان آن بخش."),
            StoryParagraph("It was a story of rebellion, and of sacrifice, and of a freedom that could not be taken away.", "داستانی بود از شورش و فداکاری و آزادی‌ای که نمی‌شد از ما گرفت."),
            StoryParagraph("It was a story that would end in death, and in life, and in the breaking of a window through which the light would pour in.", "داستانی بود که به مرگ ختم می‌شد و به زندگی و به شکستن پنجره‌ای که نور از آن می‌ریخت.")
        )
    )

    // ─────────── فصل ۳: شورش ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "Rebellion", titlePersian = "شورش",
        paragraphs = listOf(
            StoryParagraph("McMurphy began to change the ward almost immediately, and he began with small things.", "مک‌مرفی تقریباً بلافاصله شروع کرد به تغییر دادن بخش و با چیزهای کوچک شروع کرد."),
            StoryParagraph("He refused to take his pills; he said he did not want to be a zombie, like the rest of us.", "از خوردن قرص‌هایش امتناع کرد؛ گفت نمی‌خواهد مثل بقیه‌مان زامبی باشد."),
            StoryParagraph("He organized a card game — poker, for cigarettes — and he invited every patient to play.", "او یک بازی ورق ترتیب داد — پوکر، برای سیگار — و هر بیماری را دعوت کرد بازی کند."),
            StoryParagraph("He taught the patients to laugh again; he told jokes; he made jokes about the Big Nurse, about the hospital, about themselves.", "به بیماران یاد داد دوباره بخندند؛ جوک گفت؛ درباره پرستار بزرگ جوک می‌گفت، درباره بیمارستان، درباره خودشان."),
            StoryParagraph("The Big Nurse did not like the laughter; the laughter was dangerous; the laughter was contagious; the laughter could not be controlled.", "پرستار بزرگ خنده را دوست نداشت؛ خنده خطرناک بود؛ مسری بود؛ کنترل‌شدنی نبود."),
            StoryParagraph("She called McMurphy into her office, and she warned him, calmly, politely, that his behavior was inappropriate.", "مک‌مرفی را به دفترش فرا خواند و آرام، مؤدبانه هشدارش داد که رفتارش نامناسب است."),
            StoryParagraph("'What are you going to do?' McMurphy said. 'Send me to the shock shop? I've had worse.'", "مک‌مرفی گفت: «چه می‌خواهید بکنید؟ به شوک‌خانه بفرستیدم؟ از این بدتر دیده‌ام.»"),
            StoryParagraph("'There are other treatments,' the Big Nurse said, and her voice was soft, and her smile was smooth, and her eyes were cold.", "پرستار بزرگ گفت: «درمان‌های دیگری هم هست.» و صدایش نرم بود و لبخندش صاف و چشمانش سرد."),
            StoryParagraph("McMurphy learned about the treatments quickly: the electroshock, the insulin coma, the lobotomy.", "مک‌مرفی سریع درباره درمان‌ها یاد گرفت: شوک الکتریکی، کمای انسولین، لوبوتومی."),
            StoryParagraph("He learned about the patients who had been 'cured' — the ones who came back quiet and obedient and empty, the ones who were never the same.", "از بیمارانی یاد گرفت که «درمان» شده بودند — کسانی که آرام و مطیع و تهی برگشتند، کسانی که هرگز همان نشدند."),
            StoryParagraph("He learned about the Big Nurse's record: the patients who had died, the patients who had killed themselves, the patients who had simply given up.", "از سابقه پرستار بزرگ یاد گرفت: بیمارانی که مرده بودند، بیمارانی که خودکشی کرده بودند، بیمارانی که فقط تسلیم شده بودند."),
            StoryParagraph("'She kills people,' McMurphy said to me one night, when we were alone. 'She kills them slow, and she kills them legal, but she kills them.'", "مک‌مرفی یک شب که تنها بودیم به من گفت: «او آدم می‌کشد. آهسته می‌کشدش، قانونی می‌کشد، اما می‌کشدش.»"),
            StoryParagraph("'I know,' I said, but I did not say it, because I could not speak; I said it with my eyes.", "گفتم: «می‌دانم.» اما نگفتم، چون نمی‌توانستم صحبت کنم؛ با چشمانم گفتم."),
            StoryParagraph("But McMurphy understood; McMurphy always understood; he nodded, and he looked at the ward, and he said, 'We're going to fight her. We're going to fight her, and we're going to win.'", "اما مک‌مرفی فهمید؛ مک‌مرفی همیشه می‌فهمید؛ سر تکان داد و به بخش نگاه کرد و گفت: «می‌خواهیم با او بجنگیم. می‌خواهیم با او بجنگیم و می‌بریم.»"),
            StoryParagraph("And so the battle began: the battle between McMurphy and the Big Nurse, between freedom and control, between life and death.", "و اینگونه نبرد آغاز شد: نبرد میان مک‌مرفی و پرستار بزرگ، میان آزادی و کنترل، میان زندگی و مرگ."),
            StoryParagraph("The first major battle was the World Series.", "نخستین نبرد بزرگ سری جهانی بود."),
            StoryParagraph("McMurphy wanted to watch the World Series on television, but the Big Nurse said the schedule could not be changed.", "مک‌مرفی می‌خواست سری جهانی را در تلویزیون ببیند اما پرستار بزرگ گفت برنامه قابل تغییر نیست."),
            StoryParagraph("She said the ward rules were the ward rules, and the rules could not be broken, not even for a baseball game.", "گفت قوانین بخش، قوانین بخش است و قوانین نقض‌شدنی نیستند، حتی برای بازی بیسبال."),
            StoryParagraph("So McMurphy did something extraordinary: he sat down in front of the blank television screen, and he watched it anyway.", "پس مک‌مرفی کار فوق‌العاده‌ای کرد: جلوی صفحه تلویزیون خاموش نشست و به هر حال تماشایش کرد."),
            StoryParagraph("He watched the empty screen, and he commented on the plays, and he shouted at the umpire, and he cheered with the crowd.", "صفحه خالی را تماشا کرد و درباره بازی‌ها نظر داد و بر سر داور فریاد زد و با جمعیت تشویق کرد."),
            StoryParagraph("And one by one, the other patients joined him; they joined him in watching the empty screen; they joined him in pretending.", "و یکی‌یکی، بیماران دیگر به او پیوستند؛ در تماشای صفحه خالی پیوستند؛ در تظاهر پیوستند."),
            StoryParagraph("We sat there, all of us, watching nothing, and we laughed, and we shouted, and we were — for a moment — free.", "آنجا نشستیم، همه‌مان، به هیچ نگاه می‌کردیم و خندیدیم و فریاد زدیم و — برای لحظه‌ای — آزاد بودیم."),
            StoryParagraph("The Big Nurse was furious; her smooth face cracked; her calm voice rose; for a moment, just a moment, she lost control.", "پرستار بزرگ خشمگین شد؛ صورت صافش ترک خورد؛ صدای آرامش بالا رفت؛ لحظه‌ای، فقط لحظه‌ای، کنترلش را از دست داد."),
            StoryParagraph("And in that moment, I saw something that I had never seen before: I saw that she could be beaten.", "و در آن لحظه، چیزی دیدم که هرگز قبلاً ندیده بودم: دیدم که می‌شود شکستش داد."),
            StoryParagraph("Not easily, not quickly, not without cost; but she could be beaten.", "نه آسان، نه سریع، نه بدون هزینه؛ اما می‌شد شکستش داد."),
            StoryParagraph("The other patients saw it too; they began to believe; they began to hope; they began to remember that they were men.", "بیماران دیگر هم دیدند؛ شروع کردند به باور کردن؛ شروع کردند به امید داشتن؛ شروع کردند به یاد آوردن اینکه مردند."),
            StoryParagraph("McMurphy had given us that gift; McMurphy had given us hope; and we did not know — we could not know — what it would cost him.", "مک‌مرفی آن هدیه را به ما داده بود؛ مک‌مرفی امید را به ما داده بود؛ و نمی‌دانستیم — نمی‌توانستیم بدانیم — چه برایش هزینه می‌کرد."),
            StoryParagraph("But he knew; he knew from the beginning; he knew that the Big Nurse would not let him win.", "اما می‌دانست؛ از آغاز می‌دانست؛ می‌دانست پرستار بزرگ نمی‌گذارد ببرد."),
            StoryParagraph("He knew that there would be a price, and he knew that he would have to pay it, and he paid it anyway.", "می‌دانست هزینه‌ای خواهد بود و می‌دانست باید بپردازدش و به هر حال پرداخت."),
            StoryParagraph("That is what makes a hero; not the winning, but the willingness to lose; not the victory, but the courage to fight.", "این همان چیزی است که قهرمان می‌سازد؛ نه بردن، بلکه آمادگی باختن؛ نه پیروزی، بلکه شهامت جنگیدن."),
            StoryParagraph("McMurphy was a hero; he was the only hero I ever knew; and he would be destroyed by his own heroism.", "مک‌مرفی قهرمان بود؛ تنها قهرمانی بود که هرگز شناختم؛ و توسط قهرمانی خودش نابود می‌شد."),
            StoryParagraph("But before he was destroyed, he destroyed her — or at least, he damaged her in a way that could never be repaired.", "اما پیش از آنکه نابود شود، او را نابود کرد — یا حداقل، به شکلی آسیبش زد که هرگز نمی‌شد ترمیمش کرد."),
            StoryParagraph("He taught us that we did not have to be afraid; he taught us that we could laugh, and fight, and live.", "به ما آموخت که نباید بترسیم؛ آموخت که می‌توانیم بخندیم و بجنگیم و زندگی کنیم."),
            StoryParagraph("And that lesson, once learned, could never be forgotten.", "و آن درس، یک بار که آموخته شد، هرگز نمی‌شد فراموشش کرد."),
            StoryParagraph("It was the lesson of freedom; it was the lesson of dignity; it was the lesson of what it means to be a man.", "درس آزادی بود؛ درس کرامت بود؛ درس معنای انسان بودن بود."),
            StoryParagraph("And McMurphy taught it to us with his laughter, with his courage, with his life, and finally with his death.", "و مک‌مرفی با خنده‌اش آن را به ما آموخت، با شهامتش، با زندگی‌اش و در نهایت با مرگش."),
            StoryParagraph("But that is later; for now, there was still the fight, and the fight was not over.", "اما آن بعدتر است؛ برای اکنون، هنوز نبرد بود و نبرد تمام نشده بود."),
            StoryParagraph("The fight continued, day after day, week after week, and each day, McMurphy grew stronger, and each day, the Big Nurse grew angrier.", "نبرد ادامه یافت، روز پس از روز، هفته پس از هفته و هر روز، مک‌مرفی قوی‌تر شد و هر روز، پرستار بزرگ خشمگین‌تر."),
            StoryParagraph("And each day, I grew closer to finding my voice, my strength, my freedom.", "و هر روز، به یافتن صدایم نزدیک‌تر می‌شدم، قدرتم، آزادی‌ام."),
            StoryParagraph("The fog was thinning; the machine was humming louder; the moment of reckoning was approaching.", "مه نازک‌تر می‌شد؛ ماشین بلندتر همهمه می‌کرد؛ لحظه حساب نزدیک می‌شد."),
            StoryParagraph("And then, one day, it arrived.", "و بعد، یک روز، رسید.")
        )
    )

    // ─────────── فصل ۴: سفر ماهیگیری ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "The Fishing Trip", titlePersian = "سفر ماهیگیری",
        paragraphs = listOf(
            StoryParagraph("McMurphy had been planning the fishing trip for weeks.", "مک‌مرفی هفته‌ها بود که برای سفر ماهیگیری نقشه می‌کشید."),
            StoryParagraph("He had talked to the doctor — not the Big Nurse, but the young doctor who supervised the ward's medical care.", "با دکتر صحبت کرده بود — نه پرستار بزرگ، بلکه دکتر جوانی که مراقبت پزشکی بخش را نظارت می‌کرد."),
            StoryParagraph("The doctor was weak and easily persuaded, and McMurphy could persuade anyone.", "دکتر ضعیف بود و به‌راحتی قانع می‌شد و مک‌مرفی می‌توانست هر کسی را قانع کند."),
            StoryParagraph("'It would be therapeutic,' McMurphy said. 'Fresh air. Sunshine. Fishing. A chance to be men again.'", "مک‌مرفی گفت: «درمانی خواهد بود. هوای تازه. آفتاب. ماهیگیری. فرصتی برای دوباره انسان شدن.»"),
            StoryParagraph("The doctor signed the permission slip, and McMurphy got a signed permission from every patient's family — or, in some cases, forged them.", "دکتر برگه اجازه را امضا کرد و مک‌مرفی از خانواده هر بیمار امضای اجازه گرفت — یا در برخی موارد، جعلشان کرد."),
            StoryParagraph("The Big Nurse was furious, but she could not stop it; the permissions were legal, and the doctor had approved.", "پرستار بزرگ خشمگین شد اما نمی‌توانست متوقفش کند؛ اجازه‌ها قانونی بودند و دکتر تایید کرده بود."),
            StoryParagraph("So, one bright morning in early summer, a group of patients — nine of us, including me — left the hospital and headed for the coast.", "پس، یک صبح روشن در اوایل تابستان، گروهی از بیماران — نه نفر از ما، از جمله من — بیمارستان را ترک کردند و به سمت ساحل رفتند."),
            StoryParagraph("We drove in a station wagon, and we sang songs, and we laughed, and we felt — for the first time in years — like human beings.", "با استیشن واگنی راندیم و آواز خواندیم و خندیدیم و — برای نخستین بار در سال‌ها — مثل انسان‌ها احساس کردیم."),
            StoryParagraph("At the harbor, we boarded a fishing boat that McMurphy had hired, and we set out to sea.", "در بندر، سوار قایق ماهیگیری شدیم که مک‌مرفی اجاره کرده بود و به دریا رفتیم."),
            StoryParagraph("There was a woman on the boat — her name was Candy, and she was a friend of McMurphy's, and she was kind and easy-going and utterly without fear.", "زنی در قایق بود — نامش کندی بود و دوست مک‌مرفی بود و مهربان و راحت و کاملاً بی‌ترس."),
            StoryParagraph("The patients were shy at first; they had not been near a woman in years; they did not know what to say, or how to act.", "بیماران اول خجالتی بودند؛ سال‌ها نزدیک زنی نبودند؛ نمی‌دانستند چه بگویند یا چطور رفتار کنند."),
            StoryParagraph("But Candy laughed, and she joked, and she helped them bait their hooks, and soon they were talking to her like old friends.", "اما کندی خندید و جوک گفت و کمکشان کرد قلاب‌هایشان را طعمه بگذارند و به‌زودی مثل دوستان قدیمی با او صحبت می‌کردند."),
            StoryParagraph("Billy Bibbit could not stop staring at her; his stutter was worse than ever; his hands shook; his face was white.", "بیلی بیبیت نمی‌توانست از خیره شدن به او دست بکشد؛ لکنتش بدتر از همیشه بود؛ دستانش می‌لرزیدند؛ صورتش سفید بود."),
            StoryParagraph("Candy noticed, and she was gentle with him; she talked to him softly; she did not laugh at his stutter; she treated him like a man.", "کندی متوجه شد و با او لطیف بود؛ آرام با او صحبت کرد؛ به لکنتش نخندید؛ مثل یک مرد با او رفتار کرد."),
            StoryParagraph("That afternoon, we caught fish — many fish, big fish, beautiful fish — and we laughed, and we shouted, and we were happy.", "آن بعدازظهر، ماهی گرفتیم — ماهی‌های زیادی، ماهی‌های بزرگ، ماهی‌های زیبا — و خندیدیم و فریاد زدیم و خوشحال بودیم."),
            StoryParagraph("On the way back to shore, we were stopped by the harbor police.", "در راه بازگشت به ساحل، پلیس بندر ما را متوقف کرد."),
            StoryParagraph("They had been told that a group of escaped mental patients had stolen a boat.", "به آن‌ها گفته شده بود گروهی از بیماران روانی فراری قایقی دزدیده‌اند."),
            StoryParagraph("But McMurphy talked to them — of course he talked to them — and he showed them the papers, and he joked with them, and they let us go.", "اما مک‌مرفی با آن‌ها صحبت کرد — البته که صحبت کرد — و کاغذها را نشانشان داد و با آن‌ها جوک گفت و رهایمان کردند."),
            StoryParagraph("We returned to the hospital that evening, sunburned and tired and happier than we had ever been.", "آن عصر به بیمارستان برگشتیم، آفتاب‌سوخته و خسته و شادتر از هر وقت دیگری."),
            StoryParagraph("The Big Nurse was waiting for us at the door.", "پرستار بزرگ جلوی در منتظرمان بود."),
            StoryParagraph("She looked at each of us in silence, one by one, and her face was smooth, and her smile was smooth, and her eyes were cold.", "در سکوت به هر یک از ما نگاه کرد، یکی‌یکی و صورتش صاف بود و لبخندش صاف و چشمانش سرد."),
            StoryParagraph("'You have all been expelled from the fishing trip privilege,' she said. 'You will not leave this ward again.'", "گفت: «همه‌تان از امتیاز سفر ماهیگیری محروم شده‌اید. دیگر از این بخش خارج نمی‌شوید.»"),
            StoryParagraph("'The hell we won't,' McMurphy said, and he laughed, and he walked past her, into the ward.", "مک‌مرفی گفت: «به جهنم که نمی‌شویم.» و خندید و از کنارش به بخش رفت."),
            StoryParagraph("But we knew, all of us, that the punishment would come; we knew that the Big Nurse did not forget; we knew that we would pay.", "اما می‌دانستیم، همه‌مان، که مجازات می‌آید؛ می‌دانستیم پرستار بزرگ فراموش نمی‌کند؛ می‌دانستیم تاوان می‌دهیم."),
            StoryParagraph("The fishing trip had been the high point of our lives — the best day any of us could remember — and it would be the last free day for many of us.", "سفر ماهیگیری اوج زندگی‌مان بوده — بهترین روزی که هر یک از ما می‌توانست به یاد بیاورد — و آخرین روز آزاد برای بسیاری از ما می‌بود."),
            StoryParagraph("But the memory would stay with us; the memory would never fade; the memory would be something that no one could take away.", "اما خاطره با ما می‌ماند؛ خاطره هرگز محو نمی‌شد؛ خاطره چیزی می‌بود که هیچ‌کس نمی‌توانست بگیرد."),
            StoryParagraph("We had been men, for one day; we had been free, for one day; we had been alive, for one day.", "برای یک روز مرد بودیم؛ برای یک روز آزاد بودیم؛ برای یک روز زنده بودیم."),
            StoryParagraph("And one day of freedom, McMurphy taught us, is worth more than a lifetime of captivity.", "و مک‌مرفی به ما آموخت یک روز آزادی ارزشمندتر از تمام عمر اسارت است."),
            StoryParagraph("One day of truth is worth more than a lifetime of lies.", "یک روز حقیقت ارزشمندتر از تمام عمر دروغ است."),
            StoryParagraph("One day of love is worth more than a lifetime of fear.", "یک روز عشق ارزشمندتر از تمام عمر ترس است."),
            StoryParagraph("And that is what the fishing trip gave us: a day of truth, a day of love, a day of freedom.", "و این همان چیزی است که سفر ماهیگیری به ما داد: روزی از حقیقت، روزی از عشق، روزی از آزادی."),
            StoryParagraph("The Big Nurse could punish us; the Big Nurse could control us; the Big Nurse could even kill us.", "پرستار بزرگ می‌توانست مجازاتمان کند؛ می‌توانست کنترلمان کند؛ حتی می‌توانست بکشدمان."),
            StoryParagraph("But she could not take away that day; she could not take away that memory; she could not take away that freedom.", "اما نمی‌توانست آن روز را بگیرد؛ نمی‌توانست آن خاطره را بگیرد؛ نمی‌توانست آن آزادی را بگیرد."),
            StoryParagraph("That day was ours; that day would always be ours; and in that day, we had been men.", "آن روز مال ما بود؛ آن روز همیشه مال ما می‌بود؛ و در آن روز، انسان بودیم."),
            StoryParagraph("That was McMurphy's gift; that was McMurphy's genius; that was McMurphy's sacrifice.", "آن هدیه مک‌مرفی بود؛ نابغگی مک‌مرفی بود؛ فداکاری مک‌مرفی بود."),
            StoryParagraph("He gave us freedom; and in giving us freedom, he lost his own.", "او آزادی را به ما داد؛ و در دادن آزادی، آزادی خودش را از دست داد."),
            StoryParagraph("But he knew this; he knew it from the beginning; and he chose to give anyway.", "اما می‌دانست؛ از آغاز می‌دانست؛ و انتخاب کرد به هر حال بدهد."),
            StoryParagraph("That is the meaning of love; that is the meaning of sacrifice; that is the meaning of McMurphy.", "این معنای عشق است؛ این معنای فداکاری است؛ این معنای مک‌مرفی است."),
            StoryParagraph("And we, the men he saved, would never forget it.", "و ما، مردانی که نجاتشان داد، هرگز فراموشش نمی‌کردیم.")
        )
    )

    // ─────────── فصل ۵: پایان ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "The End", titlePersian = "پایان",
        paragraphs = listOf(
            StoryParagraph("The punishment came, as we knew it would, and it came in stages.", "مجازات آمد، همانطور که می‌دانستیم می‌آید و در مراحل آمد."),
            StoryParagraph("First, McMurphy was sent to the shock shop, where they strapped him to a table and sent electricity through his brain.", "اول، مک‌مرفی به شوک‌خانه فرستاده شد، جایی که او را روی میزی بستند و برق از مغزش گذراندند."),
            StoryParagraph("He came back dizzy and confused, but he was still McMurphy; he was still laughing; he was still fighting.", "گیج و سردرگم برگشت اما هنوز مک‌مرفی بود؛ هنوز می‌خندید؛ هنوز می‌جنگید."),
            StoryParagraph("Then, he was sent again; and again; and each time, he came back a little weaker, a little quieter, a little less himself.", "بعد، دوباره فرستاده شد؛ و دوباره؛ و هر بار، ضعیف‌تر برگشت، آرام‌تر، کمتر خودش."),
            StoryParagraph("But he never broke; he never surrendered; he never stopped fighting.", "اما هرگز نشکست؛ هرگز تسلیم نشد؛ هرگز از جنگیدن دست نکشید."),
            StoryParagraph("And then, one night, when the Big Nurse had pushed him too far, he did something that changed everything.", "و بعد، یک شب، وقتی پرستار بزرگ او را بیش از حد رانده بود، کاری کرد که همه چیز را تغییر داد."),
            StoryParagraph("It started with Billy Bibbit.", "با بیلی بیبیت شروع شد."),
            StoryParagraph("Billy had been getting better; the fishing trip had given him confidence; Candy had given him courage; he was beginning to believe in himself.", "بیلی بهتر شده بود؛ سفر ماهیگیری اعتماد به نفس به او داده بود؛ کندی شهامت به او داده بود؛ شروع کرده بود به باور به خودش."),
            StoryParagraph("McMurphy arranged for Billy to spend a night with Candy; he arranged it secretly, and the night was beautiful, and Billy became a man.", "مک‌مرفی ترتیب داد بیلی شبی را با کندی بگذراند؛ دزدانه ترتیب داد و شب زیبا بود و بیلی مرد شد."),
            StoryParagraph("The next morning, Billy was different; he stood taller; he spoke clearly; he smiled for the first time without stuttering.", "صبح روز بعد، بیلی متفاوت بود؛ بلندتر ایستاد؛ واضح صحبت کرد؛ برای نخستین بار بدون لکنت لبخند زد."),
            StoryParagraph("But the Big Nurse found out; she always found out; and she called Billy into her office, and she threatened him.", "اما پرستار بزرگ فهمید؛ همیشه می‌فهمید؛ و بیلی را به دفترش فرا خواند و تهدیدش کرد."),
            StoryParagraph("'I will tell your mother,' she said, and her voice was soft, and her smile was smooth. 'I will tell her what you did.'", "گفت: «به مادرت می‌گویم.» و صدایش نرم بود و لبخندش صاف. «می‌گویم چه کردی.»"),
            StoryParagraph("Billy was terrified; his mother was the only person he truly feared; her disapproval was worse than any punishment.", "بیلی وحشت کرد؛ مادرش تنها کسی بود که واقعاً از او می‌ترسید؛ نارضایتی او بدتر از هر مجازاتی بود."),
            StoryParagraph("'Please,' he begged. 'Please don't tell her.'", "التماس کرد: «لطفاً. لطفاً به او نگویید.»"),
            StoryParagraph("'I have no choice,' the Big Nurse said. 'It is my duty.'", "پرستار بزرگ گفت: «چاره‌ای ندارم. وظیفه‌ام است.»"),
            StoryParagraph("Billy broke; he broke completely; he broke like a man who had been holding himself together for years and who could hold himself together no longer.", "بیلی شکست؛ کاملاً شکست؛ مثل مردی شکست که سال‌ها خودش را نگه داشته بود و دیگر نمی‌توانست نگه دارد."),
            StoryParagraph("He ran to the ward's supply room, and he found a scalpel, and he cut his own throat.", "او به انبار بخش دوید و چاقوی جراحی پیدا کرد و گلویش را برید."),
            StoryParagraph("When we found him, he was lying in a pool of blood, and he was dead, and his face was peaceful for the first time in his life.", "وقتی پیدایش کردیم، در حوضچه‌ای از خون دراز کشیده بود و مرده بود و صورتش برای نخستین بار در زندگی‌اش آرام بود."),
            StoryParagraph("McMurphy was destroyed by Billy's death; he had loved Billy; he had tried to save Billy; and he had failed.", "مک‌مرفی توسط مرگ بیلی نابود شد؛ بیلی را دوست داشت؛ تلاش کرده بود نجاتش دهد؛ و شکست خورده بود."),
            StoryParagraph("But the Big Nurse was not sorry; the Big Nurse was not even moved; the Big Nurse simply said, 'This is a tragedy, and we must all learn from it.'", "اما پرستار بزرگ متأسف نبود؛ حتی متأثر نبود؛ تنها گفت: «این تراژدی است و همه باید از آن درس بگیریم.»"),
            StoryParagraph("And McMurphy, hearing those words, lost control; he lost control completely; and he attacked her.", "و مک‌مرفی با شنیدن آن کلمات کنترلش را از دست داد؛ کاملاً از دست داد؛ و به او حمله کرد."),
            StoryParagraph("He threw himself at the Big Nurse, and he grabbed her by the throat, and he squeezed, and he squeezed, and he would have killed her if the guards had not pulled him off.", "خودش را روی پرستار بزرگ انداخت و گلویش را گرفت و فشار داد و فشار داد و اگر نگهبانان نکشیده بودندش می‌کشتش."),
            StoryParagraph("The guards pulled him off; they beat him; they dragged him away; and we did not see him again for many weeks.", "نگهبانان کشیدندش؛ کتکش زدند؛ بردنش؛ و هفته‌های بسیاری دوباره ندیدیمش."),
            StoryParagraph("When he finally returned, he was not McMurphy anymore; he was a vegetable; he had been given a lobotomy.", "وقتی سرانجام برگشت، دیگر مک‌مرفی نبود؛ سبزی بود؛ لوبوتومی داده بودندش."),
            StoryParagraph("He could not walk; he could not speak; he could not think; he could only lie in his bed, breathing, blinking, existing.", "نمی‌توانست راه برود؛ نمی‌توانست صحبت کند؛ نمی‌توانست فکر کند؛ تنها می‌توانست در تختش دراز بکشد، نفس بکشد، پلک بزند، وجود داشته باشد."),
            StoryParagraph("The patients looked at him, and they wept, and they did not know what to do.", "بیماران نگاهش کردند و گریستند و نمی‌دانستند چه کنند."),
            StoryParagraph("The Big Nurse had won; she had finally won; she had destroyed the man who had dared to fight her.", "پرستار بزرگ برده بود؛ سرانجام برده بود؛ مردی که جرات جنگیدن با او را داشت نابود کرده بود."),
            StoryParagraph("But she had not destroyed the memory; she had not destroyed the lesson; she had not destroyed what McMurphy had taught us.", "اما خاطره را نابود نکرده بود؛ درس را نابود نکرده بود؛ آنچه مک‌مرفی به ما آموخته بود را نابود نکرده بود."),
            StoryParagraph("And that night, I made a decision; I decided that I would not let him live like this; I decided that I would set him free.", "و آن شب، تصمیمی گرفتم؛ تصمیم گرفتم نگذارم اینطور زندگی کند؛ تصمیم گرفتم آزادش کنم."),
            StoryParagraph("I went to his bed, and I looked at him, and I saw — for the last time — the man he had been.", "به تختش رفتم و نگاهش کردم و — برای آخرین بار — مردی که بوده را دیدم."),
            StoryParagraph("And then, gently, I put a pillow over his face, and I held it there, and I held it until he stopped breathing.", "و بعد، به‌آرامی، بالشی روی صورتش گذاشتم و آنجا نگه داشتم و نگه داشتم تا نفس نکشید."),
            StoryParagraph("It was the kindest thing I could do; it was the only thing I could do; it was the last gift I could give him.", "مهربانانه‌ترین کاری بود که می‌توانستم بکنم؛ تنها کاری بود که می‌توانستم بکنم؛ آخرین هدیه‌ای بود که می‌توانستم به او بدهم."),
            StoryParagraph("I did it out of love; I did it out of gratitude; I did it out of freedom.", "از عشق این کار را کردم؛ از سپاس؛ از آزادی."),
            StoryParagraph("Then I lifted the heavy control panel — the one he had told me I could lift — and I threw it through the window.", "بعد پنل کنترل سنگین را بلند کردم — همان که به من گفته بود می‌توانم بلندش کنم — و از پنجره پرت کردم."),
            StoryParagraph("The window broke; the glass shattered; and the light poured in; and I ran out into the night.", "پنجره شکست؛ شیشه خرد شد؛ و نور به داخل ریخت؛ و من به شب بیرون دویدم."),
            StoryParagraph("I ran, and I ran, and I ran, and I did not look back.", "دویدم و دویدم و دویدم و عقب نگاه نکردم."),
            StoryParagraph("I ran toward the mountains, toward my father's old land, toward the freedom that McMurphy had given me.", "به سمت کوه‌ها دویدم، به سمت سرزمین کهن پدرم، به سمت آزادی‌ای که مک‌مرفی به من داده بود."),
            StoryParagraph("And as I ran, I spoke — for the first time in years — I spoke aloud, and my voice was strange to my own ears, and it was beautiful.", "و همانطور که می‌دویدم، صحبت کردم — برای نخستین بار در سال‌ها — بلند صحبت کردم و صدایم برای گوش‌های خودم عجیب بود و زیبا بود."),
            StoryParagraph("'I am free,' I said. 'I am free. I am free.'", "گفتم: «آزادم. آزادم. آزادم.»"),
            StoryParagraph("And so I flew over the cuckoo's nest, and I left the machine behind, and I became a man again.", "و اینگونه بر فراز آشیانه فاخته پرواز کردم و ماشین را پشت سر گذاشتم و دوباره انسان شدم."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("One Flew Over the Cuckoo's Nest, published in 1962, is one of the most important American novels of the twentieth century.", "پرواز بر فراز آشیانه فاخته، منتشرشده در ۱۹۶۲، یکی از مهم‌ترین رمان‌های آمریکایی قرن بیستم است."),
            StoryParagraph("It was written by Ken Kesey, who worked as an orderly in a mental hospital and who drew on that experience to create his masterpiece.", "توسط کِن کِیزی نوشته شد، که به‌عنوان بهیار در بیمارستان روانی کار می‌کرد و از آن تجربه برای خلق شاهکارش بهره برد."),
            StoryParagraph("The novel is set in a mental hospital in Oregon, and it tells the story of a rebellion against a tyrannical nurse.", "رمان در بیمارستانی روانی در اورگان می‌گذرد و داستان شورشی علیه پرستاری مستبد را تعریف می‌کند."),
            StoryParagraph("But the novel is not just about mental illness; it is about power, about freedom, about what it means to be human.", "اما رمان تنها درباره بیماری روانی نیست؛ درباره قدرت است، درباره آزادی، درباره معنای انسان بودن."),
            StoryParagraph("The Big Nurse represents the forces of control in modern society: the institutions, the bureaucracies, the systems that crush individuality.", "پرستار بزرگ نماینده نیروهای کنترل در جامعه مدرن است: نهادها، بوروکراسی‌ها، نظام‌هایی که فردیت را خرد می‌کنند."),
            StoryParagraph("She is not a villain in the traditional sense; she does not shout, she does not beat, she does not torture — at least, not physically.", "او شرور به معنای سنتی نیست؛ فریاد نمی‌زند، کتک نمی‌زند، شکنجه نمی‌کند — حداقل نه فیزیکی."),
            StoryParagraph("Instead, she controls through a thousand small mechanisms: the schedule, the pills, the meetings, the silences, the smiles.", "در عوض، از طریق هزار مکانیزم کوچک کنترل می‌کند: برنامه، قرص‌ها، جلسات، سکوت‌ها، لبخندها."),
            StoryParagraph("She is the embodiment of what the philosopher Michel Foucault called 'disciplinary power' — the power that works not by force, but by normalization.", "او تجسم چیزی است که فیلسوف میشل فوکو «قدرت انضباطی» نامید — قدرتی که نه با زور، بلکه با عادی‌سازی کار می‌کند."),
            StoryParagraph("Her goal is not to punish, but to make everyone the same; not to hurt, but to homogenize; not to destroy, but to make all patients obedient.", "هدفش مجازات نیست، بلکه یکسان کردن همه است؛ نه آسیب، بلکه همگن‌سازی؛ نه نابودی، بلکه مطیع کردن همه بیماران."),
            StoryParagraph("McMurphy represents the opposite force: freedom, individuality, resistance, life.", "مک‌مرفی نماینده نیروی مخالف است: آزادی، فردیت، مقاومت، زندگی."),
            StoryParagraph("He is loud and crude and selfish; he is not a saint; he is a gambler and a con man.", "پرصدا و خام و خودخواه است؛ قدیس نیست؛ قمارباز و کلاهبردار است."),
            StoryParagraph("But he is also the only person in the novel who refuses to be controlled, who insists on being himself, who laughs in the face of power.", "اما همچنین تنها کسی در رمان است که از کنترل شدن امتناع می‌کند، که اصرار دارد خودش باشد، که در برابر قدرت می‌خندد."),
            StoryParagraph("His laughter is his weapon; his laughter is his rebellion; his laughter is his freedom.", "خنده‌اش سلاحش است؛ خنده‌اش شورشش است؛ خنده‌اش آزادی‌اش است."),
            StoryParagraph("And in laughing, he teaches the other patients to laugh; in being free, he teaches them to be free; in being human, he teaches them to be human.", "و در خندیدن، به بیماران دیگر می‌آموزد بخندند؛ در آزاد بودن، می‌آموزد آزاد باشند؛ در انسان بودن، می‌آموزد انسان باشند."),
            StoryParagraph("Chief Bromden is the narrator, and his voice is one of the most distinctive in American literature.", "رئیس برومدن راوی است و صدایش یکی از متمایزترین در ادبیات آمریکایی است."),
            StoryParagraph("He is a Chronic, a man who has given up, a man who has been in the hospital for so long that he has forgotten what freedom looks like.", "او مزمنی است، مردی که تسلیم شده، مردی که آنقدر طولانی در بیمارستان بوده که فراموش کرده آزادی چه شکلی است."),
            StoryParagraph("But through his eyes, we see the truth of the ward; through his ears, we hear the machine; through his memory, we understand what has been lost.", "اما از چشمانش، حقیقت بخش را می‌بینیم؛ از گوش‌هایش، ماشین را می‌شنویم؛ از حافظه‌اش، می‌فهمیم چه از دست رفته."),
            StoryParagraph("The fog that descends on the ward is both real and symbolic; it is the fog of oppression, the fog of fear, the fog of forgetting.", "مهی که بر بخش نازل می‌شود هم واقعی است و هم نمادین؛ مه ظلم است، مه ترس، مه فراموشی."),
            StoryParagraph("When the fog lifts — when McMurphy arrives — Bromden begins to remember who he is.", "وقتی مه بلند می‌شود — وقتی مک‌مرفی می‌رسد — برومدن شروع می‌کند به یاد آوردن کیست."),
            StoryParagraph("The novel's central theme is the conflict between freedom and control, between individuality and conformity, between life and death-in-life.", "مضمون محوری رمان تضاد میان آزادی و کنترل است، میان فردیت و همرنگی، میان زندگی و مرگ-در-زندگی."),
            StoryParagraph("The Big Nurse wants everyone to be the same; McMurphy wants everyone to be themselves.", "پرستار بزرگ می‌خواهد همه یکسان باشند؛ مک‌مرفی می‌خواهد همه خودشان باشند."),
            StoryParagraph("The Big Nurse wants order; McMurphy wants chaos; the Big Nurse wants silence; McMurphy wants laughter.", "پرستار بزرگ نظم می‌خواهد؛ مک‌مرفی آشوب؛ پرستار بزرگ سکوت می‌خواهد؛ مک‌مرفی خنده."),
            StoryParagraph("And in the end, though McMurphy is destroyed — lobotomized, turned into a vegetable — his spirit lives on in Bromden, who escapes and becomes free.", "و در پایان، هرچند مک‌مرفی نابود می‌شود — لوبوتومی‌شده، به سبزی تبدیل‌شده — روحش در برومدن زنده می‌ماند، که فرار می‌کند و آزاد می‌شود."),
            StoryParagraph("The novel is, in this sense, a tragedy with a hopeful ending; McMurphy dies, but his death is not in vain; his death is a sacrifice that makes Bromden's freedom possible.", "رمان از این نظر تراژدی‌ای با پایان امیدوارکننده است؛ مک‌مرفی می‌میرد اما مرگش بی‌فایده نیست؛ مرگش فداکاری‌ای است که آزادی برومدن را ممکن می‌کند."),
            StoryParagraph("The title of the novel comes from a children's rhyme: 'One flew east, one flew west, one flew over the cuckoo's nest.'", "عنوان رمان از یک شعر کودکانه می‌آید: «یکی به شرق پرید، یکی به غرب، یکی بر فراز آشیانه فاخته پرید.»"),
            StoryParagraph("The cuckoo's nest is the mental hospital; the bird that flies over it is Bromden, who escapes.", "آشیانه فاخته بیمارستان روانی است؛ پرنده‌ای که بر فرازش می‌پرد برومدن است، که فرار می‌کند."),
            StoryParagraph("But the bird that flies over could also be McMurphy, whose spirit escapes even though his body is destroyed.", "اما پرنده‌ای که بر فراز می‌پرد می‌تواند مک‌مرفی هم باشد، که روحش فرار می‌کند هرچند بدنش نابود شده."),
            StoryParagraph("Or it could be the reader, who, having read the novel, is invited to fly over the cuckoo's nest of their own society.", "یا می‌تواند خواننده باشد، که با خواندن رمان، دعوت می‌شود بر فراز آشیانه فاخته جامعه خودش بپرد."),
            StoryParagraph("For the novel is not just about a mental hospital in Oregon in the 1960s; it is about every institution, every system, every society that tries to make people the same.", "زیرا رمان تنها درباره بیمارستانی روانی در اورگان دهه ۱۹۶۰ نیست؛ درباره هر نهاد، هر نظام، هر جامعه‌ای است که تلاش می‌کند مردم را یکسان کند."),
            StoryParagraph("It is about the schools that crush creativity, the workplaces that demand conformity, the governments that suppress dissent, the cultures that punish difference.", "درباره مدارسی است که خلاقیت را خرد می‌کنند، محل‌های کاری که همرنگی می‌طلبند، دولت‌هایی که مخالفت را سرکوب می‌کنند، فرهنگ‌هایی که تفاوت را مجازات می‌کنند."),
            StoryParagraph("And it is about the McMurphys of the world, who refuse to be crushed, who insist on being themselves, who laugh in the face of power — and who pay the price.", "و درباره مک‌مرفی‌های جهان است، که از خرد شدن امتناع می‌کنند، که اصرار دارند خودشان باشند، که در برابر قدرت می‌خندند — و تاوان می‌دهند."),
            StoryParagraph("But their sacrifice is not in vain; it plants seeds; it lights fires; it opens windows through which others can escape.", "اما فداکاریشان بی‌فایده نیست؛ بذر می‌کارد؛ آتش می‌افروزد؛ پنجره‌هایی می‌گشاید که دیگران از آن‌ها فرار کنند."),
            StoryParagraph("McMurphy planted seeds in Bromden; Bromden escaped; and Bromden's story, told in this novel, plants seeds in us.", "مک‌مرفی در برومدن بذر کاشت؛ برومدن فرار کرد؛ و داستان برومدن، در این رمان گفته‌شده، در ما بذر می‌کارد."),
            StoryParagraph("And we, having read it, are invited to fly over the cuckoo's nest of our own lives — to escape the fog, to break the machine, to become free.", "و ما، با خواندنش، دعوت می‌شویم بر فراز آشیانه فاخته زندگی خودمان بپریم — از مه بگریزیم، ماشین را بشکنیم، آزاد شویم."),
            StoryParagraph("The novel does not promise that escape is easy; it does not promise that freedom is comfortable; it does not promise that rebellion will succeed.", "رمان وعده نمی‌دهد فرار آسان است؛ وعده نمی‌دهد آزادی راحت است؛ وعده نمی‌دهد شورش موفق می‌شود."),
            StoryParagraph("But it promises that escape is possible; that freedom is worth fighting for; that rebellion, even when it fails, is not in vain.", "اما وعده می‌دهد فرار ممکن است؛ آزادی ارزش جنگیدن دارد؛ شورش، حتی وقتی شکست می‌خورد، بی‌فایده نیست."),
            StoryParagraph("And that promise — that quiet, stubborn, unkillable promise — is what makes One Flew Over the Cuckoo's Nest one of the great books of the twentieth century.", "و آن وعده — آن وعده آرام، سرسخت، نابودنشدنی — همان چیزی است که پرواز بر فراز آشیانه فاخته را به یکی از کتاب‌های بزرگ قرن بیستم تبدیل می‌کند."),
            StoryParagraph("It is a book about madness, and about sanity; about disease, and about health; about death, and about life.", "کتابی است درباره جنون و درباره عقل؛ درباره بیماری و درباره سلامت؛ درباره مرگ و درباره زندگی."),
            StoryParagraph("And, above all, it is a book about freedom — about what it costs, and about why it is worth the cost.", "و بیش از همه، کتابی است درباره آزادی — درباره اینکه چه هزینه‌ای دارد و چرا ارزش هزینه را دارد."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For the story of Chief Bromden does not end with the last page; it begins there, in the heart of every reader who has been touched by it.", "زیرا داستان رئیس برومدن با صفحه آخر پایان نمی‌یابد؛ آنجا آغاز می‌شود، در قلب هر خواننده‌ای که توسط آن لمس شده."),
            StoryParagraph("And every reader who has been touched by it, has been changed by it; and every reader who has been changed by it, will never be the same.", "و هر خواننده‌ای که توسط آن لمس شده، توسط آن تغییر یافته؛ و هر خواننده‌ای که توسط آن تغییر یافته، هرگز همان نخواهد بود.")
        )
    )
}